'use strict';

var { Given, When, Then, Before } = require('@cucumber/cucumber');
var assert = require('node:assert');

// ============================================================
// Helpers
// ============================================================

function getTodoList(world) {
  return world.document.querySelectorAll('.todo-list li');
}

function findTodoItem(world, title) {
  var items = getTodoList(world);
  for (var i = 0; i < items.length; i++) {
    var label = items[i].querySelector('label');
    if (label && label.textContent === title) return items[i];
  }
  return null;
}

function triggerEvent(world, el, eventType, options) {
  var KeyboardEvent = world.window.KeyboardEvent;
  var MouseEvent = world.window.MouseEvent;
  var opts = options || {};
  opts.bubbles = true;
  var isKeyboard = eventType === 'keyup' || eventType === 'keydown' || eventType === 'keypress';
  var isMouse = eventType === 'click' || eventType === 'dblclick' || eventType === 'mousedown' || eventType === 'mouseup';
  var evt;
  if (isKeyboard && typeof KeyboardEvent === 'function') {
    evt = new KeyboardEvent(eventType, opts);
  } else if (isMouse && typeof MouseEvent === 'function') {
    evt = new MouseEvent(eventType, opts);
  } else {
    evt = new world.window.Event(eventType, opts);
  }
  el.dispatchEvent(evt);
}

// ============================================================
// Given
// ============================================================

Given('I visit the TodoMVC app', function () {
  // The world.js Before hook already loads the app
  // Ensure we start on the All filter
  this.navigate('#/');
});

Given('the todo list is empty', function () {
  // App is already loaded fresh; confirm empty
  var items = getTodoList(this);
  assert.strictEqual(items.length, 0);
});

Given('I have a todo {string}', function (title) {
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
});

Given('I have an active todo {string}', function (title) {
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
});

Given('I have a completed todo {string}', function (title) {
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  var item = findTodoItem(this, title);
  if (item) {
    item.querySelector('.toggle').click();
  }
});

Given('I have todos {string} and {string}', function (todo1, todo2) {
  var input = this.document.querySelector('.new-todo');
  input.value = todo1;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  input.value = todo2;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
});

Given('I have completed todos {string} and {string}', function (todo1, todo2) {
  var input = this.document.querySelector('.new-todo');
  input.value = todo1;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  input.value = todo2;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  var item1 = findTodoItem(this, todo1);
  if (item1) item1.querySelector('.toggle').click();
  var item2 = findTodoItem(this, todo2);
  if (item2) item2.querySelector('.toggle').click();
});

Given('I have active todo {string} and completed todo {string}', function (active, completed) {
  var input = this.document.querySelector('.new-todo');
  input.value = active;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  input.value = completed;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  var item = findTodoItem(this, completed);
  if (item) item.querySelector('.toggle').click();
});

Given('I am editing the todo {string}', function (title) {
  // Create the todo first
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
  // Double-click to enter editing mode
  var item = findTodoItem(this, title);
  assert.ok(item, 'Todo item "' + title + '" should exist');
  var label = item.querySelector('label');
  triggerEvent(this, label, 'dblclick', { bubbles: true });
  assert.ok(item.classList.contains('editing'), 'Todo item should be in editing mode');
});

// ============================================================
// When
// ============================================================

When('I type {string} into the new todo input and press enter', function (text) {
  var input = this.document.querySelector('.new-todo');
  input.value = text;
  triggerEvent(this, input, 'keyup', { keyCode: 13 });
});

When('I click the checkbox for {string}', function (title) {
  var item = findTodoItem(this, title);
  assert.ok(item, 'Todo item "' + title + '" should exist');
  var toggle = item.querySelector('.toggle');
  toggle.click();
});

When('I click the {string} toggle', function (label) {
  var toggleAll = this.document.querySelector('#toggle-all');
  toggleAll.click();
});

When('I complete {string}', function (title) {
  var item = findTodoItem(this, title);
  assert.ok(item, 'Todo item "' + title + '" should exist');
  var toggle = item.querySelector('.toggle');
  toggle.click();
});

When('I also complete {string}', function (title) {
  var item = findTodoItem(this, title);
  assert.ok(item, 'Todo item "' + title + '" should exist');
  item.querySelector('.toggle').click();
});

When('I double-click the label for {string}', function (title) {
  var item = findTodoItem(this, title);
  assert.ok(item, 'Todo item "' + title + '" should exist');
  var label = item.querySelector('label');
  triggerEvent(this, label, 'dblclick', { bubbles: true });
});

When('I change the text to {string} and blur the edit input', function (newText) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An edit input should be visible');
  editInput.value = newText;
  triggerEvent(this, editInput, 'focusout', { bubbles: true });
});

When('I change the text to {string} and press enter', function (newText) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An edit input should be visible');
  editInput.value = newText;
  triggerEvent(this, editInput, 'keyup', { keyCode: 13 });
});

When('I change the text to {string} and press escape', function (newText) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An edit input should be visible');
  editInput.value = newText;
  triggerEvent(this, editInput, 'keyup', { keyCode: 27 });
});

When('I clear the text and press enter', function () {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'An edit input should be visible');
  editInput.value = '';
  triggerEvent(this, editInput, 'keyup', { keyCode: 13 });
});

When('I click the destroy button for {string}', function (title) {
  var item = findTodoItem(this, title);
  assert.ok(item, 'Todo item "' + title + '" should exist');
  var destroy = item.querySelector('.destroy');
  destroy.click();
});

When('I click the {string} button', function (label) {
  // "Clear completed" button
  var btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'Clear completed button should exist');
  btn.click();
});

When('I reload the page', function () {
  var self = this;
  // Save the current localStorage content before disposing
  var data = this.localStorage.getItem('todos-vanillajs');
  var filterHash = this.window.location.hash;
  // Dispose the current app (destroys the window and its localStorage)
  this.disposeApp();
  // Manually reload: create a new window, restore localStorage data BEFORE the app reads it
  var fs = require('node:fs');
  var path = require('node:path');
  var ROOT = path.resolve(__dirname, '..', '..');
  var { Window } = require('happy-dom');
  this.window = new Window({ url: 'http://localhost/', settings: { disableJavaScriptFileLoading: true } });
  this.document = this.window.document;
  // Restore localStorage data before the app initializes
  if (data !== null) {
    this.localStorage.setItem('todos-vanillajs', data);
  }
  // Now load the page and app code
  this.document.write(fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8'));
  this.document.close();
  this.window.eval(fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8'));
