this.$toggleAll.checked = this.model.allCompleted();

// Update DOM in-place to preserve existing element references
var existingItems = {};
var children = this.$todoList.children;
for (var i = 0; i < children.length; i++) {
  var li = children[i];
  if (li.tagName === 'LI' && li.dataset.id) {
    existingItems[li.dataset.id] = li;
  }
}

var fragment = this.$todoList.ownerDocument.createDocumentFragment();
filteredTodos.forEach(function (todo) {
  var existing = existingItems[todo.id];
  if (existing) {
    // Update existing element
    existing.className = todo.completed ? 'completed' : '';
    var toggle = existing.querySelector('.toggle');
    if (toggle) toggle.checked = todo.completed;
    var label = existing.querySelector('label');
    if (label) label.textContent = todo.title;
    var edit = existing.querySelector('.edit');
    if (edit) edit.value = todo.title;
    delete existingItems[todo.id];
    fragment.appendChild(existing);
  } else {
    var liClass = '';
    if (todo.completed) liClass += 'completed';
    var html = '<li data-id="' + todo.id + '" class="' + liClass + '">';
    html += '<div class="view">';
    html += '<input class="toggle" type="checkbox" ' + (todo.completed ? 'checked' : '') + '>';
    html += '<label>' + TodoController.escapeHtml(todo.title) + '</label>';
    html += '<button class="destroy"></button>';
    html += '</div>';
    html += '<input class="edit" value="' + TodoController.escapeHtml(todo.title) + '">';
    html += '</li>';
    var temp = document.createElement('div');
    temp.innerHTML = html;
    fragment.appendChild(temp.firstChild);
  }
});

// Remove items that no longer exist
for (var id in existingItems) {
  if (existingItems.hasOwnProperty(id)) {
    existingItems[id].parentNode.removeChild(existingItems[id]);
  }
}

this.$todoList.appendChild(fragment);

